+	// Se RW disponibile (nessun writer e nessun lettore), acquisisci
+	if (p->writer == 0 && p->nreaders == 0) {
+		p->writer = esecuzione->id;
+	} else {
+		// Altrimenti, metti in coda e sospendi
+		inserimento_lista(p->w_writers, esecuzione);
