 }

@@ -1963,6 +1971,21 @@ extern "C" void c_rw_acq_read(natl rw)
 	}

 // ( SOLUZIONE 2026-01-28
+	// Se writer non attivo, meno di MAX_RW_READERS lettori, e nessun writer
+	// in attesa (fairness: nuovi lettori solo se non ci sono scrittori in attesa)
+	if (p->writer == 0 && p->nreaders < MAX_RW_READERS && p->w_writers == nullptr) {
+		for (int i = 0; i < MAX_RW_READERS; i++) {
+			if (p->readers[i] == 0) {
+				p->readers[i] = esecuzione->id;
+				p->nreaders++;
+				break;
+			}
+		}
+	} else {
+		// Altrimenti, metti in coda e sospendi
+		inserimento_lista(p->w_readers, esecuzione);
+		schedulatore();
+	}
 //   SOLUZIONE 2026-01-28 )
 }

@@ -1988,6 +2011,29 @@ extern "C" void c_rw_rel_write(natl rw)
 	}

 // ( SOLUZIONE 2026-01-28
+	p->writer = 0;
+	// Priorità ai lettori: sveglia tutti i lettori in attesa fino al limite
+	while (p->w_readers && p->nreaders < MAX_RW_READERS) {
+		des_proc* lavoro = rimozione_lista(p->w_readers);
+		for (int i = 0; i < MAX_RW_READERS; i++) {
+			if (p->readers[i] == 0) {
+				p->readers[i] = lavoro->id;
+				p->nreaders++;
+				break;
+			}
+		}
+		inspronti();
+		inserimento_lista(pronti, lavoro);
+		schedulatore();
+	}
+	// Se non ci sono lettori attivi e c'è uno scrittore in attesa, sveglialo
+	if (p->w_writers && p->nreaders == 0) {
+		des_proc* lavoro = rimozione_lista(p->w_writers);
+		p->writer = lavoro->id;
+		inspronti();
+		inserimento_lista(pronti, lavoro);
+		schedulatore();
+	}
 //   SOLUZIONE 2026-01-28 )
 }

@@ -2010,6 +2056,36 @@ extern "C" void c_rw_rel_read(natl rw)
 	}

 // ( SOLUZIONE 2026-01-28
+	// Rimuovi questo processo dall'array readers
+	for (int i = pos + 1; i < MAX_RW_READERS; i++) {
+		p->readers[i - 1] = p->readers[i];
+	}
+	p->readers[MAX_RW_READERS - 1] = 0;
+	p->nreaders--;
+	// Se non ci sono più lettori, priorità agli scrittori
+	if (p->nreaders == 0 && p->w_writers) {
+		des_proc* lavoro = rimozione_lista(p->w_writers);
+		p->writer = lavoro->id;
+		inspronti();
+		inserimento_lista(pronti, lavoro);
+		schedulatore();
+	}
+	// Altrimenti, sveglia lettori in attesa
+	else if (p->w_readers && p->nreaders < MAX_RW_READERS) {
+		while (p->w_readers && p->nreaders < MAX_RW_READERS) {
+			des_proc* lavoro = rimozione_lista(p->w_readers);
+			for (int i = 0; i < MAX_RW_READERS; i++) {
+				if (p->readers[i] == 0) {
+					p->readers[i] = lavoro->id;
+					p->nreaders++;
+					break;
+				}
+			}
+			inspronti();
+			inserimento_lista(pronti, lavoro);
+			schedulatore();
+		}
+	}
 //   SOLUZIONE 2026-01-28 )
 }
 // ESAME 2026-01-28 )
